//! Unsealed full STAT data over genuine original raw-policy page loans.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,reactive_raw_policy_pages::RawPolicyPages,sparse_slots_policy::Output,stats_policy::Builder,key_policy_control::Control};
use std::{collections::{BTreeMap,HashMap},io,sync::Arc};
struct Scratch{budget:Arc<Budget>,ok:bool}impl Drop for Scratch{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
fn oom(budget:&Budget,message:impl Into<String>)->Failure{budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn check(budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{budget.require().map_err(|m|oom(budget,m))?;poll()?;budget.require().map_err(|m|oom(budget,m))}
struct Native<'a>{budget:&'a Budget,poll:&'a dyn Fn()->io::Result<()>}impl Control for Native<'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{check(self.budget,self.poll)}fn reserve(&mut self,n:usize)->Result<(),Failure>{self.budget.charge(n).map_err(|m|oom(self.budget,m))}fn overflow(&mut self)->Failure{oom(self.budget,"Stats scanner admission overflow")}fn allocation_failed(&mut self)->Failure{self.overflow()}}
fn retained(out:&Output)->Option<usize>{out.diags.iter().try_fold(out.body.capacity().checked_add(out.diags.capacity().checked_mul(std::mem::size_of::<crate::sparse_slots_policy::Diagnostic>())?)?,|n,d|n.checked_add(d.rel.capacity())?.checked_add(d.msg.capacity()))}
/// Data only: the actual host must prove original include order and exhausted
/// CODE_DM scope. Membership is lexical ancestry, never semantic parent_type.
pub fn generate_from_pages(pages:&dyn RawPolicyPages,order:&HashMap<String,usize>,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<Output,Failure>{
 check(root,poll)?;let mut scratch=Scratch{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&scratch.budget;
 let result=(||{
  let rows=crate::reactive_raw_policy_pages::collect_marker_rows(|visit|pages.for_each(visit),order,budget,&["STAT"],false,false,false,&mut||check(budget,poll).map_err(|e|match e{Failure::Operational(e)=>e,Failure::Unsupported(m)=>io::Error::other(m)}),&||check(budget,poll))?;
  let mut builder=Builder::captured(Arc::clone(budget));for marker in &rows.markers{check(budget,poll)?;builder.push(&marker.rel,marker.line,&marker.args);check(budget,poll)?;}
  let mut requested:BTreeMap<String,BTreeMap<String,bool>>=BTreeMap::new();for(mut ty,name)in builder.requests(){loop{check(budget,poll)?;if !requested.get(ty).is_some_and(|names|names.contains_key(name)){budget.charge(ty.len().checked_add(name.len()).and_then(|n|n.checked_mul(2)).and_then(|n|n.checked_add(4096)).ok_or_else(||oom(budget,"Stats membership directory overflow"))?).map_err(|m|oom(budget,m))?;requested.entry(ty.to_owned()).or_default().insert(name.to_owned(),false);}match ty.rfind('/'){Some(0)|None=>break,Some(at)=>ty=&ty[..at]}}}
  if !requested.is_empty(){let complete=pages.for_each(&mut|relative,views|{check(budget,poll)?;if relative.ends_with("_generated/stats.dm"){return Ok(true)}let clean=views.clean(budget)?;let mut control=Native{budget:views.allocation_budget(budget),poll};crate::raw_type_vars_policy::visit_with(clean,&mut control,&mut|ty,name|{if let Some(found)=requested.get_mut(ty).and_then(|names|names.get_mut(name)){*found=true;}Ok(())})?;Ok(true)})?;if !complete{return Err("Stats membership traversal stopped before exhaustion".into())}}
  let mut out=builder.finish_with(|ty,name|crate::stats_policy::declares_var(|owner,key|requested.get(owner).and_then(|names|names.get(key)).copied().unwrap_or(false),ty,name),||check(budget,poll))?;check(budget,poll)?;root.charge(retained(&out).ok_or_else(||oom(root,"Stats output capacity overflow"))?).map_err(|m|oom(root,m))?;let mut owned=Output::default();owned.body=std::mem::take(&mut out.body);owned.diags=std::mem::take(&mut out.diags);drop(out);Ok(owned)
 })();
 let result=match result{Err(Failure::Operational(actual))=>Err(Failure::Operational(actual)),other if budget.denied()=>{drop(other);Err(oom(budget,"Stats operation denied"))},other=>{check(budget,poll)?;other}};scratch.ok=result.is_ok();drop(scratch);if matches!(&result,Err(Failure::Operational(_))){return result}check(root,poll)?;result
}

#[cfg(test)]#[path="stats_policy_frozen_original.rs"]mod original_stats;
#[cfg(test)]mod tests{
 use super::*;use super::original_stats as original;use crate::captured_raw_file::{File,RawPolicyViews};use std::cell::Cell;
 struct Pages{files:Vec<File>,fail:Cell<bool>,stop:Cell<bool>}impl RawPolicyPages for Pages{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{for file in &self.files{if !file.with_policy_views(visit)?{return Ok(false)}}if self.fail.get(){return Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}Ok(!self.stop.get())}}
 fn fixture()->Pages{let root=std::env::current_dir().unwrap().join("stats-page-data");let sources=[("code/a.dm","/obj/a\n    var/existing\nSTAT(/obj/a/child, existing, SUM)\nSTAT(/obj/a/child, missing, ALL)\n"),("code/engine/_generated/stats.dm","/obj/a/child/var/missing\n")];Pages{files:sources.into_iter().map(|(name,text)|File::capture(&root,&root.join(name),text.to_owned().into()).unwrap()).collect(),fail:Cell::new(false),stop:Cell::new(false)}}
 #[test]fn stats_pages_keep_original_clean_lexical_membership_and_exclude_only_own_previous_output(){let pages=fixture();let budget=Budget::new(8*1024*1024).unwrap();let before=budget.used();let out=generate_from_pages(&pages,&HashMap::new(),&budget,&||Ok(())).unwrap();assert_eq!(budget.used()-before,retained(&out).unwrap()+std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>(),"only funded output and existing fixed scratch metadata may remain");let mut old=original::Builder::default();old.push("code/a.dm",3,&["/obj/a/child".to_owned(),"existing".to_owned(),"SUM".to_owned()]);old.push("code/a.dm",4,&["/obj/a/child".to_owned(),"missing".to_owned(),"ALL".to_owned()]);let old=old.finish(|ty,name|original::declares_var(|owner,key|owner=="/obj/a"&&key=="existing",ty,name));assert_eq!(out.body,old.body);assert_eq!(out.diags,old.diags);assert!(!out.body.contains("/var/existing ="));assert!(out.body.contains("/obj/a/child/var/missing = TRUE"));assert!(out.diags.is_empty());assert!(out.body.contains("__stat_existing"));drop(pages);assert!(out.body.contains("__stat_missing"));}
 #[test]fn stats_page_duplicate_order_is_original_include_rank_not_walk_order(){let root=std::env::current_dir().unwrap().join("stats-page-order");let files=[("code/a.dm","STAT(/obj/a, same, ANY)\n"),("code/z.dm","STAT(/obj/a, same, ALL)\n")].into_iter().map(|(name,text)|File::capture(&root,&root.join(name),text.to_owned().into()).unwrap()).collect();let pages=Pages{files,fail:Cell::new(false),stop:Cell::new(false)};let order=HashMap::from([("code/z.dm".to_owned(),0),("code/a.dm".to_owned(),1)]);let out=generate_from_pages(&pages,&order,&Budget::new(8*1024*1024).unwrap(),&||Ok(())).unwrap();assert!(out.body.find("\"ALL\"").unwrap()<out.body.find("\"ANY\"").unwrap());}
 #[test]fn stats_pages_preserve_actual_io_stopped_and_quota_before_later_cancel_then_retry(){let pages=fixture();pages.fail.set(true);assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&Budget::new(8*1024*1024).unwrap(),&||Ok(())),Err(Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));pages.fail.set(false);pages.stop.set(true);assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&Budget::new(8*1024*1024).unwrap(),&||Ok(())),Err(Failure::Unsupported(_))));pages.stop.set(false);let tiny=Budget::new(4096).unwrap();assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&tiny,&||if tiny.denied(){Err(io::ErrorKind::Interrupted.into())}else{Ok(())}),Err(Failure::Operational(ref e))if e.kind()==io::ErrorKind::OutOfMemory));assert!(!generate_from_pages(&pages,&HashMap::new(),&Budget::new(8*1024*1024).unwrap(),&||Ok(())).unwrap().body.is_empty());}
 #[test]fn original_clean_view_is_lazily_funded_only_when_demanded(){let pages=fixture();let tiny=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();pages.files[0].with_policy_views(&mut|_,view|{assert!(view.raw()?.contains("var/existing"));assert!(!tiny.denied());let error=view.clean(&tiny).err().unwrap();assert!(matches!(error,Failure::Operational(ref e)if e.kind()==io::ErrorKind::OutOfMemory));Ok(true)}).unwrap();assert!(tiny.denied());let root=Budget::new(1024*1024).unwrap();pages.files[0].with_policy_views(&mut|_,view|{assert!(view.clean(&root)?.contains("var/existing"));Ok(true)}).unwrap();}
 #[test]fn original_clean_page_credit_dies_after_actual_file_drop_instead_of_accumulating_across_code(){let root=std::env::current_dir().unwrap().join("stats-clean-loan");let source:dm_preprocess::SourceText=format!("/obj/a\n{}", "    var/name // same original clean\n".repeat(1024)).into();let budget=Budget::new(8*1024*1024).unwrap();let fallback=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let before=budget.used();let fixed=std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>();for page in 0..80{crate::captured_raw_file::with_original_policy_file(&root,&root.join("code/a.dm"),source.clone(),source.len(),&budget,&mut|_,views|{assert!(views.clean(&fallback)?.contains("var/name"));assert!(budget.used()>before);Ok(true)}).unwrap();assert_eq!(budget.used(),before+(page+1)*fixed,"physical File/clean backing retires; preexisting conservative Arc/payload metadata remains per page");}assert!(!fallback.denied());assert!(!budget.denied());}

}
